121	+/* ============================ Lái xe máy: điều phối chế độ (lái một mình, máy tính) ============================
122	+   Spec D-040. Cấu trúc theo explore/drive/index.ts; dùng lại các phần thuần của chế độ ô tô (mạng đường, va chạm, camera sau xe, HUD),
123	+   drive/* không bao giờ import ngược từ bike/*.
124	+   - Mạng đường DÙNG CHUNG với ô tô: drEnsureNet() của drive/index.ts (dựng một lần cho cả trang; drCollectRuntime chỉ push, dựng net thứ hai sẽ nhân đôi vật cản).
125	+   - Thân va chạm: start() đặt drUseBody(BK_BODY), stop() trả DR_CAR_BODY (drive.start() cũng tự đặt lại thân ô tô).
126	+   - Mỗi khung: phím → BkInput (keys.ts), grip = 1 (Task 7 nối thời tiết), bkStep với hộp xe tự động gần xe (trNearby), hình xe (model.ts),
127	+     camera góc thứ ba = drCamPlace với CONFIG.bike.cam3, controls.target theo xe (tâm vùng bóng đổ), HUD (đồng hồ + bản đồ nhỏ của ô tô), exNightStep(dt, false).
128	+   - Phím (theo e.code, chỉ khi đang lái, bỏ ô nhập và tổ hợp Ctrl / Meta / Alt; blur / ẩn tab nhả hết): R về làn (bkRecover), Q / E xi nhan trái / phải (bkSignal),
129	+     V đổi góc nhìn (góc thứ nhất ở Task 5, giờ chỉ có góc thứ ba). Còi H: âm thanh ở Task 8.
130	+   - Lớp body 'explore drive bike': khung HUD #drHud và các quy tắc CSS của body.drive áp nguyên; 'bike' cho phần riêng về sau.
131	+   - Thoát: explore.exit() gọi bike.stop() rồi tải lại trang. Chưa có: nhiều người (Task 10), cảm ứng (Task 9), mô hình thật (Task 3).
132	+   Mỗi khung không cấp phát (D-018). */
133	+import { scene, camera, controls, canvas } from '../../core/renderer';
134	+import { onResize } from '../../core/postprocessing';
135	+import { cam } from '../../views/state';
136	+import { CONFIG } from '../../config';
137	+import { driveView } from '../../environment/driveRoads';
138	+import { drSetGate, type DrNet } from '../drive/net';
139	+import { DR_GATE_SWING } from '../drive/roadData';
140	+import { drUseBody, DR_CAR_BODY, type DrBox } from '../drive/collide';
141	+import { drCamPlace, drCamDrag, type DrCam } from '../drive/camera';
142	+import { drBindDrop } from '../drive/keys';
143	+import { drHudShow, drHudHide, drHudUpdate, type DrMapDot } from '../drive/hud';
144	+import { drEnsureNet } from '../drive';
145	+import { trNearby } from '../../common/trafficQuery';
146	+import { exNightStep } from '../nightShows';
147	+import { bkCreate, bkStep, bkRecover, bkSignal, bkPitch, BK_BODY, type BkState, type BkInput } from './motion';
148	+import { bkInputFromKeys, BK_KEYS } from './keys';
149	+import { BkBike } from './model';
150	+import type { SwingController } from '../../bridges/song-han/SwingController';
151	+
152	+const BK_SOLO_SLOT = -1;   // bkCreate / drSpawnPose: lái một mình xuất phát ở giữa các chỗ của slot (trên Cầu Rồng, đi Đông, bên phải)
153	+const K3 = CONFIG.bike.cam3;
154	+const NO_DOTS: DrMapDot[] = [];   // lái một mình: bản đồ nhỏ không có xe người khác
155	+
156	+let net: DrNet | null = null;
157	+let state: BkState | null = null;
158	+let ctrl: SwingController | null = null;
159	+let model: BkBike | null = null;   // hình xe của mình, dựng lần đầu vào chế độ
160	+let view: 1 | 3 = 3;
161	+const bkKeys = new Set<string>();   // e.code đang giữ
162	+const camS: DrCam = { yaw: 0, pitch: 0, idle: 0 };
163	+const _inp: BkInput = { gas: 0, brake: 0, steer: 0, hard: false, grip: 1 };   // đầu vào tái dùng mỗi khung
164	+const boxes: DrBox[] = [];          // hộp xe tự động gần xe, tái dùng mỗi khung
165	+let saved: { fov: number; near: number; explore: boolean } | null = null;   // thứ start() đổi, stop() trả lại
166	+
167	+const active = () => cam.mode === 'bike' && state !== null;
168	+const inMode = () => active();     // chế độ xem (hết chỗ) ở Task 10
169	+const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
170	+
171	+/* Một bước: cổng nhịp quay, chuyển động (sơ tán nằm trong bkStep), hình xe, camera, HUD, hiệu ứng đêm */
172	+function advance(dt: number, inp: BkInput): void {
173	+  const s = state!, n = net!;
174	+  if (ctrl) drSetGate(n, DR_GATE_SWING, ctrl.state !== 'CLOSED');
175	+  bkStep(s, inp, n, boxes, trNearby(s.x, s.z, CONFIG.drive.ai.radius, boxes), dt);
176	+  model!.place(s);
177	+  drCamPlace(camera, s, camS, n, dt, false, K3);
178	+  controls.target.set(s.x, s.y, s.z);   // tâm vùng bóng đổ (main.ts shadowCenter) theo xe
179	+  drHudUpdate(s, NO_DOTS);
180	+  exNightStep(dt, false);
181	+}
182	+
183	+/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
184	+function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
185	+  if (!net || !model) return;
186	+  const s = bkCreate(net, BK_SOLO_SLOT);
187	+  let gy = -Infinity;
188	+  for (const p of net.pads) {
189	+    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
190	+    gy = Math.max(gy, p.y(x, z));
191	+  }
192	+  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
193	+  bkPitch(s, net);
194	+  state = s;
195	+  camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
196	+  model.place(s);
197	+  drCamPlace(camera, s, camS, net, 0, true, K3);
198	+  controls.target.set(s.x, s.y, s.z);
199	+}
200	+
201	+export const bike = {
202	+  active,
203	+  inMode,
204	+  get state(): BkState | null { return state; },
205	+  get net(): DrNet | null { return net; },
206	+  get view(): 1 | 3 { return view; },
207	+  /* Đổi góc nhìn: góc thứ nhất làm ở Task 5, giờ luôn góc thứ ba */
208	+  setView(v: 1 | 3): void { view = v === 1 ? 3 : v; },
209	+  /* Vào lái một mình */
210	+  start(): void {
211	+    drUseBody(BK_BODY);
212	+    const n = drEnsureNet();
213	+    net = n;
214	+    state = bkCreate(n, BK_SOLO_SLOT);
215	+    camS.yaw = 0; camS.pitch = 0; camS.idle = 0;
216	+    if (!model) model = new BkBike();
217	+    scene.add(model.group);
218	+    model.place(state);
219	+    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
220	+    bkKeys.clear();
221	+    drHudShow(n);
222	+    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
223	+    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
224	+    camera.fov = K3.fov; onResize();          // onResize cập nhật ma trận chiếu và hệ số cỡ điểm theo fov mới
225	+    drCamPlace(camera, state, camS, n, 0, true, K3);
226	+    controls.target.set(state.x, state.y, state.z);
227	+    document.body.classList.add('explore', 'drive', 'bike');
228	+  },
229	+  update(dt: number): void {
230	+    if (!active()) return;
231	+    bkInputFromKeys(bkKeys, _inp);
232	+    _inp.grip = 1;                            // Task 7: theo thời tiết (weatherU.uWet), khô trong hầm kín
233	+    advance(dt, _inp);
234	+  },
235	+  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
236	+  afterRender(): void { /* chưa có việc */ },
237	+  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
238	+  stop(): void {
239	+    if (state === null) return;
240	+    state = null; bkKeys.clear();
241	+    drHudHide();
242	+    model?.group.removeFromParent();
243	+    driveView.far = 1;
244	+    drUseBody(DR_CAR_BODY);
245	+    document.body.classList.remove('drive', 'bike');
246	+    if (saved) {
247	+      if (!saved.explore) document.body.classList.remove('explore');
248	+      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
249	+      saved = null;
250	+    }
251	+    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
252	+  },
253	+  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
254	+  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
